intramuralRoutes.patch("/intramurals/:id", async (req, res) => {
  const user = me(req);
  const id = Number(req.params.id);
  await requirePermission(user, "schedules.edit", id);
  const s = setupInput.parse(req.body);
  if (s.sessionStart && s.sessionEnd && s.sessionEnd <= s.sessionStart) throw new HttpError(400, "The session must end after it starts");
  const cols = {
    name: s.name,
    short_code: s.shortCode?.toUpperCase(),
    color: s.color,
    coordinator_name: s.coordinatorName,
    session_weekday: s.sessionWeekday,
    session_start: s.sessionStart,
    session_end: s.sessionEnd,
    location: s.location,
    dress_code: s.dressCode,
    default_schedule: s.defaultSchedule && JSON.stringify([...s.defaultSchedule].sort((a, b) => a.time.localeCompare(b.time))),
    default_roles: s.defaultRoles && JSON.stringify(s.defaultRoles),
    categories: s.categories && JSON.stringify(s.categories),
    teams: s.teams && JSON.stringify(s.teams),
    availability_options: s.availabilityOptions && JSON.stringify(s.availabilityOptions)
  };
  const set2 = Object.entries(cols).filter(([, v]) => v !== void 0);
  if (set2.length) {
    await query(`UPDATE intramurals SET ${set2.map(([k], n) => `${k} = $${n + 2}`).join(", ")} WHERE id = $1`, [id, ...set2.map(([, v]) => v)]);
    await query(
      `UPDATE sessions s SET start_time = i.session_start, end_time = i.session_end, location = i.location, dress_code = i.dress_code,
              schedule = i.default_schedule
         FROM intramurals i WHERE i.id = s.intramural_id AND s.intramural_id = $1 AND s.kind = 'training'
          AND s.version = 1 AND s.date >= current_date`,
      [id]
    );
    await ensureUpcomingSessions(id);
  }
  await audit(user.id, "setup_updated", { intramuralId: id, fields: set2.map(([k]) => k) });
  res.json({ ok: true });
});
